import os
import sys
import re
import requests
from pathlib import Path
from typing import Optional

# Add project root to path if running as module
project_root = Path(__file__).resolve().parent.parent.parent
if str(project_root) not in sys.path:
    sys.path.insert(0, str(project_root))

from src.utils.logging import setup_logging, log_with_context, get_global_error_tracker

logger = setup_logging("fetcher")

def read_verified_url(file_path: str) -> str:
    """Read the verified template URL from the file generated by T009a."""
    path = Path(file_path)
    if not path.exists():
        raise FileNotFoundError(f"Verified URL file not found: {path}")
    
    content = path.read_text(encoding='utf-8').strip()
    if not content:
        raise ValueError("Verified URL file is empty")
    
    logger.info(f"Read verified URL from {file_path}: {content}")
    return content

def fetch_url_content(url: str, timeout: int = 30) -> str:
    """Fetch raw HTML content from the URL."""
    logger.info(f"Fetching content from URL: {url}")
    try:
        response = requests.get(url, timeout=timeout)
        response.raise_for_status()
        return response.text
    except requests.RequestException as e:
        logger.error(f"Failed to fetch URL {url}: {e}")
        raise

def extract_protocol_content(html_content: str) -> Optional[str]:
    """
    Extract protocol content from HTML.
    Looks for <div class="protocol"> or specific section headers.
    Falls back to extracting the main body if specific tags are not found,
    but logs a warning.
    """
    # Strategy 1: Look for <div class="protocol">
    pattern_protocol = r'<div\s+class="protocol"(.*?)>(.*?)</div>'
    match = re.search(pattern_protocol, html_content, re.DOTALL | re.IGNORECASE)
    if match:
        logger.info("Found protocol content in <div class=\"protocol\">")
        return match.group(2).strip()

    # Strategy 2: Look for <section class="protocol"> or similar
    pattern_section = r'<section[^>]*class="protocol"[^>]*>(.*?)</section>'
    match = re.search(pattern_section, html_content, re.DOTALL | re.IGNORECASE)
    if match:
        logger.info("Found protocol content in <section class=\"protocol\">")
        return match.group(1).strip()

    # Strategy 3: Look for specific headers like "## Protocol" or "<h2>Protocol</h2>"
    # This is a fallback for markdown-in-html or mixed content
    pattern_header = r'(?:<h2[^>]*>Protocol</h2>|## Protocol)(.*?)(?:<h2|<h3|$)'
    match = re.search(pattern_header, html_content, re.DOTALL | re.IGNORECASE)
    if match:
        logger.info("Found protocol content after 'Protocol' header")
        return match.group(1).strip()

    # Fallback: If no specific tag found, return the whole body but warn
    logger.warning("Specific protocol tags not found. Returning full body content.")
    body_match = re.search(r'<body[^>]*>(.*?)</body>', html_content, re.DOTALL | re.IGNORECASE)
    if body_match:
        return body_match.group(1).strip()
    
    return html_content.strip()

def clean_html_tags(text: str) -> str:
    """Remove HTML tags while preserving text content and newlines."""
    # Remove script and style elements
    clean = re.sub(r'<(script|style)[^>]*>.*?</\1>', '', text, flags=re.DOTALL | re.IGNORECASE)
    # Remove HTML tags
    clean = re.sub(r'<[^>]+>', ' ', clean)
    # Decode HTML entities (basic)
    clean = clean.replace('&nbsp;', ' ')
    clean = clean.replace('&amp;', '&')
    clean = clean.replace('&lt;', '<')
    clean = clean.replace('&gt;', '>')
    clean = clean.replace('&quot;', '"')
    clean = clean.replace('&#39;', "'")
    # Normalize whitespace
    clean = re.sub(r'\s+', ' ', clean)
    clean = clean.strip()
    # Preserve paragraph breaks (convert multiple spaces/newlines to double newline)
    clean = re.sub(r'\s*\n\s*', '\n', clean)
    return clean

def save_protocol_content(content: str, output_path: str) -> None:
    """Save the extracted protocol content to a Markdown file."""
    path = Path(output_path)
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(content, encoding='utf-8')
    logger.info(f"Saved protocol content to {output_path} ({len(content)} bytes)")

def main():
    """Main entry point for T009b: Fetch and Normalize Template."""
    logger.info("Starting T009b: Fetch and Normalize Template")
    
    try:
        # 1. Read verified URL
        verified_url_file = "assets/templates/verified_template_url.txt"
        url = read_verified_url(verified_url_file)
        
        # 2. Fetch content
        raw_html = fetch_url_content(url)
        
        # 3. Extract protocol content
        protocol_text = extract_protocol_content(raw_html)
        if not protocol_text:
            raise ValueError("Could not extract any protocol content from the fetched page.")
        
        # 4. Clean HTML tags
        clean_text = clean_html_tags(protocol_text)
        
        # 5. Save to output file
        output_file = "assets/templates/TEMPLATE-001-v1.0.md"
        save_protocol_content(clean_text, output_file)
        
        logger.info("T009b completed successfully.")
        return 0
    
    except Exception as e:
        logger.error(f"T009b failed: {e}")
        get_global_error_tracker().record_error("T009b", str(e))
        return 1

if __name__ == "__main__":
    sys.exit(main())
